components.css:
.ds-job { list-style: none; padding: 12px 0; font-family: Geist, ui-sans-serif, system-ui, sans-serif; }
.ds-job-head { display: flex; align-items: center; justify-content: space-between; gap: 12px; margin-bottom: 6px; }
.ds-job-id { min-width: 0; }
.ds-job-name { margin: 0; font-size: 14px; font-weight: 500; letter-spacing: -0.006em; color: var(--fg, #171B24); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.ds-job-stage { margin: 2px 0 0; font-size: 12px; color: var(--fg-muted, #525C6E); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.ds-job-controls { display: flex; align-items: center; gap: 4px; flex-shrink: 0; }
.ds-job-chip { border-radius: 9999px; padding: 2px 8px; font-size: 11px; font-weight: 500; white-space: nowrap; }
.ds-job-chip--processing { background: var(--brand-soft, #E8F6F4); color: var(--brand-soft-text, #0B615A); }
.ds-progress { height: 6px; width: 100%; overflow: hidden; border-radius: 9999px; background: var(--muted, #ECEEF2); }
.ds-progress-fill { height: 100%; border-radius: 9999px; transition: width 200ms cubic-bezier(0.22, 1, 0.36, 1); }
.ds-progress-fill--processing { background: var(--brand, #0F7A72); }
.ds-icon-btn { display: inline-flex; align-items: center; justify-content: center; height: 28px; width: 28px; border-radius: 10px; border: 1px solid var(--line, #DDE1E8); background: var(--surface, #fff); color: var(--fg-muted, #525C6E); cursor: pointer; transition: background-color 150ms, border-color 150ms, color 150ms; }
.ds-icon-btn:hover { background: var(--hover, #E7EAEF); color: var(--fg, #171B24); }
.ds-icon-btn:focus-visible { outline: none; box-shadow: 0 0 0 2px color-mix(in srgb, var(--brand, #0F7A72) 70%, transparent); }
.ds-icon-btn--danger { border-color: color-mix(in srgb, var(--danger, #C6413B) 30%, transparent); color: var(--danger-text, #A5322D); }
.ds-icon-btn--danger:hover { background: var(--danger-soft, #FCECEC); color: var(--danger-text, #A5322D); }
.ds-touch { position: relative; }
@media (pointer: coarse) { .ds-touch::after { content: ""; position: absolute; top: 50%; left: 50%; width: max(100%, 44px); height: max(100%, 44px); transform: translate(-50%, -50%); } }
@media (prefers-reduced-motion: reduce) { .ds-progress-fill { transition: none; } }

.ds-bars { display: flex; flex-direction: column; gap: 10px; font-family: Geist, ui-sans-serif, system-ui, sans-serif; }
.ds-bar-row { display: grid; grid-template-columns: 88px 1fr; align-items: center; gap: 12px; }
.ds-bar-label { font-size: 11px; font-weight: 500; color: var(--fg-muted, #525C6E); }
.ds-progress { height: 6px; width: 100%; overflow: hidden; border-radius: 9999px; background: var(--muted, #ECEEF2); }
.ds-progress-fill { height: 100%; border-radius: 9999px; transition: width 200ms cubic-bezier(0.22, 1, 0.36, 1); }
.ds-f-queued { background: var(--fg-subtle, #697485); }
.ds-f-processing { background: var(--brand, #0F7A72); }
.ds-f-paused { background: var(--warn-text, #8F5E12); }
.ds-f-done { background: var(--ok-text, #0E6D4A); }
.ds-f-failed { background: var(--danger, #C6413B); }
.ds-f-cancelled { background: var(--line-strong, #C4CBD5); }
.ds-f-indeterminate { background: var(--fg-subtle, #697485); animation: ds-pulse 1.6s ease-in-out infinite; }
@keyframes ds-spin { to { transform: rotate(360deg); } } @keyframes ds-pulse { 0%,100% { opacity: 1; } 50% { opacity: .45; } }
@media (prefers-reduced-motion: reduce) { .ds-progress-fill { transition: none; animation: none; } }

.ds-chips { display: flex; flex-wrap: wrap; gap: 6px; font-family: Geist, ui-sans-serif, system-ui, sans-serif; }
.ds-chip { display: inline-flex; align-items: center; gap: 4px; border-radius: 9999px; padding: 2px 8px; font-size: 11px; font-weight: 500; white-space: nowrap; }
.ds-chip--idle { background: var(--muted, #ECEEF2); color: var(--fg-muted, #525C6E); }
.ds-chip--brand { background: var(--brand-soft, #E8F6F4); color: var(--brand-soft-text, #0B615A); }
.ds-chip--warn { background: var(--warn-soft, #FCF3E6); color: var(--warn-text, #8F5E12); }
.ds-chip--ok { background: var(--ok-soft, #E9F7EF); color: var(--ok-text, #0E6D4A); }
.ds-chip--danger { background: var(--danger-soft, #FCECEC); color: var(--danger-text, #A5322D); }
.ds-chip-spin { animation: ds-spin 900ms linear infinite; }
@keyframes ds-spin { to { transform: rotate(360deg); } } @keyframes ds-pulse { 0%,100% { opacity: 1; } 50% { opacity: .45; } }
@media (prefers-reduced-motion: reduce) { .ds-chip-spin { animation: none; } }

.ds-picker { display: flex; flex-wrap: wrap; gap: 8px; font-family: Geist, ui-sans-serif, system-ui, sans-serif; }
.ds-pick-btn { display: inline-flex; align-items: center; gap: 8px; height: 40px; padding: 0 16px; border-radius: 10px; border: 1px solid var(--line, #DDE1E8); background: var(--surface, #fff); color: var(--fg, #171B24); font-family: inherit; font-size: 14px; font-weight: 500; letter-spacing: -0.006em; cursor: pointer; transition: background-color 150ms, border-color 150ms; }
.ds-pick-btn:hover { border-color: var(--line-strong, #C4CBD5); background: var(--hover, #E7EAEF); }
.ds-pick-btn:focus-visible { outline: none; box-shadow: 0 0 0 2px color-mix(in srgb, var(--brand, #0F7A72) 70%, transparent); }
.ds-pick-btn:disabled { opacity: .5; pointer-events: none; }

.ds-masthead { position: relative; overflow: hidden; border-radius: 14px; padding: 26px 28px; font-family: Geist, ui-sans-serif, system-ui, sans-serif; background: linear-gradient(105deg, #C9560C 0%, #F5842F 46%, #FFAB5E 100%); box-shadow: 0 18px 40px -18px rgba(245,132,47,0.55); }
.ds-masthead-texture { position: absolute; inset: 0; background-image: radial-gradient(rgba(255,255,255,0.16) 1px, transparent 1px); background-size: 16px 16px; opacity: .5; }
.ds-masthead-inner { position: relative; display: flex; align-items: center; justify-content: space-between; gap: 24px; flex-wrap: wrap; }
.ds-masthead-copy { max-width: 560px; }
.ds-masthead-pill { display: inline-flex; align-items: center; gap: 7px; height: 24px; padding: 0 10px; border-radius: 9999px; background: rgba(0,0,0,0.22); color: #fff; font-size: 11px; font-weight: 600; line-height: 1; text-transform: uppercase; letter-spacing: 0.08em; margin-bottom: 12px; }
.ds-masthead-dot { width: 6px; height: 6px; border-radius: 9999px; background: #fff; }
.ds-masthead-title { margin: 0; font-size: 24px; line-height: 29px; font-weight: 600; letter-spacing: -0.02em; color: #fff; text-wrap: balance; }
.ds-masthead-sub { margin: 8px 0 0; font-size: 13px; line-height: 19px; color: rgba(255,255,255,0.82); }
.ds-masthead-kpis { display: flex; gap: 12px; flex-shrink: 0; }
.ds-kpi { text-align: center; padding: 14px 20px; border-radius: 12px; background: rgba(0,0,0,0.2); }
.ds-kpi-value { font-family: 'Geist Mono', ui-monospace, SFMono-Regular, Menlo, monospace; font-size: 28px; line-height: 1; font-weight: 600; color: #fff; font-variant-numeric: tabular-nums; }
.ds-kpi-label { margin-top: 6px; font-size: 11px; line-height: 1; font-weight: 500; text-transform: uppercase; letter-spacing: 0.06em; color: rgba(255,255,255,0.8); }

.ds-stats { display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 16px; font-family: Geist, ui-sans-serif, system-ui, sans-serif; }
.ds-stat { text-align: left; border-radius: 14px; border: 1px solid var(--line, #DDE1E8); background: var(--surface, #fff); padding: 20px; }
.ds-stat--alert { border-color: color-mix(in srgb, var(--warn-text, #8F5E12) 30%, var(--line, #DDE1E8)); cursor: pointer; font-family: inherit; transition: background-color 150ms; }
.ds-stat--alert:hover { background: var(--muted, #ECEEF2); }
.ds-stat--alert:focus-visible { outline: none; box-shadow: 0 0 0 2px color-mix(in srgb, var(--brand, #0F7A72) 70%, transparent); }
.ds-stat-top { display: flex; align-items: flex-start; justify-content: space-between; }
.ds-stat-label { font-size: 12px; line-height: 1; font-weight: 500; text-transform: uppercase; letter-spacing: 0.05em; color: var(--fg-subtle, #697485); }
.ds-stat-tile { display: flex; height: 32px; width: 32px; align-items: center; justify-content: center; border-radius: 9px; }
.ds-tile-brand { background: var(--brand-soft, #E8F6F4); color: var(--brand-text, #0B615A); }
.ds-tile-warn { background: var(--warn-soft, #FCF3E6); color: var(--warn-text, #8F5E12); }
.ds-stat-value { margin-top: 10px; font-size: 30px; line-height: 36px; font-weight: 600; letter-spacing: -0.02em; font-variant-numeric: tabular-nums; color: var(--fg, #171B24); }
.ds-stat-value--warn { color: var(--warn-text, #8F5E12); }
.ds-stat-sub { margin-top: 4px; font-size: 12px; line-height: 1; color: var(--fg-subtle, #697485); }

.ds-panel { border-radius: 14px; border: 1px solid var(--line, #DDE1E8); background: var(--surface, #fff); padding: 20px 24px; font-family: Geist, ui-sans-serif, system-ui, sans-serif; }
.ds-panel-head { display: flex; align-items: center; gap: 8px; margin-bottom: 16px; }
.ds-panel-tile { display: flex; height: 28px; width: 28px; align-items: center; justify-content: center; border-radius: 8px; background: var(--c-violet-soft, #F3E9FC); color: var(--c-violet, #8B3FD4); }
.ds-panel-title { margin: 0; font-size: 15px; line-height: 1; font-weight: 500; color: var(--fg, #171B24); }
.ds-donut-row { display: flex; align-items: center; gap: 24px; flex-wrap: wrap; }
.ds-donut { flex-shrink: 0; transform: rotate(-90deg); }
.ds-legend { flex: 1; min-width: 180px; display: flex; flex-direction: column; gap: 12px; }
.ds-legend-row { display: flex; align-items: center; gap: 10px; }
.ds-sw { width: 10px; height: 10px; border-radius: 3px; flex-shrink: 0; }
.ds-legend-label { flex: 1; font-size: 13px; color: var(--fg-muted, #525C6E); }
.ds-legend-val { font-family: 'Geist Mono', ui-monospace, SFMono-Regular, Menlo, monospace; font-size: 14px; font-weight: 600; font-variant-numeric: tabular-nums; color: var(--fg, #171B24); }
.ds-legend-pct { width: 44px; text-align: right; font-family: 'Geist Mono', ui-monospace, SFMono-Regular, Menlo, monospace; font-size: 12px; color: var(--fg-subtle, #697485); }

.ds-panel { border-radius: 14px; border: 1px solid var(--line, #DDE1E8); background: var(--surface, #fff); padding: 20px 24px; font-family: Geist, ui-sans-serif, system-ui, sans-serif; }
.ds-panel-head { display: flex; align-items: center; gap: 8px; margin-bottom: 4px; }
.ds-panel-tile--sky { background: var(--c-sky-soft, #E3F1FB); color: var(--c-sky, #1F7BB8); }
.ds-panel-sub { margin: 0 0 16px; font-size: 12px; color: var(--fg-subtle, #697485); }
.ds-bars { display: flex; flex-direction: column; gap: 14px; }
.ds-barhead { display: flex; align-items: center; justify-content: space-between; margin-bottom: 6px; gap: 12px; }
.ds-barname { font-size: 13px; color: var(--fg, #171B24); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.ds-barcount { font-family: 'Geist Mono', ui-monospace, SFMono-Regular, Menlo, monospace; font-size: 13px; font-weight: 600; font-variant-numeric: tabular-nums; color: var(--fg-muted, #525C6E); flex-shrink: 0; }
.ds-bartrack { height: 6px; border-radius: 9999px; background: var(--muted, #ECEEF2); overflow: hidden; }
.ds-barfill { height: 100%; border-radius: 9999px; background: var(--brand, #0F7A72); transition: width 200ms cubic-bezier(0.22, 1, 0.36, 1); }
@media (prefers-reduced-motion: reduce) { .ds-barfill { transition: none; } }
